begin; create extension if not exists pgtap with schema extensions; select no_plan();
-- Test-only privileged seeding (ADR-0103): clients can no longer insert program
-- rows; fixtures that only need an existing root bypass the product flow on
-- purpose here. Rolled back with the test transaction; never in production.
create function public.test_seed_program_root(p_id uuid, p_name text, p_athlete uuid default null, p_goal uuid default null) returns void language sql security definer set search_path='' as $seed$
  insert into public.training_programs(id,athlete_id,athlete_goal_id,name) values(p_id,coalesce(p_athlete,public.current_athlete_id()),p_goal,p_name) $seed$;
grant execute on function public.test_seed_program_root(uuid,text,uuid,uuid) to authenticated;
select has_table('public','training_programs','programs table exists'); select has_table('public','training_blocks','blocks table exists'); select has_table('public','training_weeks','weeks table exists'); select has_table('public','training_days','days table exists'); select has_table('public','exercise_prescriptions','prescriptions table exists'); select has_table('public','prescription_sets','sets table exists');
select has_column('public','training_programs','supersedes_program_id','revision lineage exists'); select has_column('public','prescription_sets','target_metric','target metric exists'); select has_column('public','prescription_sets','load_kg','metric load exists');
select ok(exists(select 1 from pg_indexes where indexname='training_programs_one_active_per_athlete'),'one-active partial index exists'); select is((select count(*) from pg_class where relnamespace='public'::regnamespace and relname in ('training_programs','training_blocks','training_weeks','training_days','exercise_prescriptions','prescription_sets') and relrowsecurity),6::bigint,'RLS enabled on all tables');
select ok(not has_table_privilege('anon','public.training_programs','select'),'anon has no access'); select ok(has_table_privilege('authenticated','public.training_programs','select'),'authenticated has grant');
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','phase5a@example.invalid'),('22222222-2222-4222-8222-222222222222','phase5b@example.invalid'); insert into public.athletes(id,user_id) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','22222222-2222-4222-8222-222222222222');
insert into public.athlete_goals(id,athlete_id,goal_type) values('a1000000-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','strength'),('b1000000-0000-4000-8000-000000000001','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','strength');
set local request.jwt.claim.sub='11111111-1111-4111-8111-111111111111'; set local role authenticated;
-- ADR-0103: clients hold no INSERT privilege on program rows at all.
select throws_ok($$insert into public.training_programs(athlete_id,name,status,activated_at) values(public.current_athlete_id(),'Bypass','active',now())$$,'42501',null,'authenticated cannot insert a program row (active)');
select throws_ok($$insert into public.training_programs(athlete_id,name) values(public.current_athlete_id(),'Raiz vazia')$$,'42501',null,'authenticated cannot insert an empty draft root');
-- Table guards still hold for privileged writers.
reset role;
select throws_ok($$insert into public.training_programs(athlete_id,name,status,activated_at) values(public.current_athlete_id(),'Bypass','active',now())$$,'55000',null,'program cannot be inserted active');
select throws_ok($$insert into public.training_programs(athlete_id,name,athlete_goal_id) values(public.current_athlete_id(),'Cross goal','b1000000-0000-4000-8000-000000000001')$$,'23503',null,'cross-athlete goal rejected');
set local role authenticated;
select public.test_seed_program_root('a2000000-0000-4000-8000-000000000001','Programa A',null,'a1000000-0000-4000-8000-000000000001');
select public.test_seed_program_root('a2000000-0000-4000-8000-000000000002','Vazio'); select throws_ok($$select public.activate_training_program('a2000000-0000-4000-8000-000000000002')$$,'23514',null,'empty activation rejected'); delete from public.training_programs where id='a2000000-0000-4000-8000-000000000002';
select lives_ok($$select public.replace_training_program_structure('a2000000-0000-4000-8000-000000000001','{"blocks":[{"sequence":1,"name":"Base","weeks":[{"sequence":1,"name":"W1","days":[{"sequence":1,"name":"A","prescriptions":[{"sequence":1,"exerciseId":"50000000-0000-4000-8000-000000000001","sets":[{"sequence":1,"targetMetric":"reps","targetMin":8,"targetMax":10,"rirMin":2,"rirMax":2,"restMinSeconds":120,"restMaxSeconds":120,"tempo":"3-1-X-0","loadKind":"absolute","loadKg":30}]}]}]}]}]}'::jsonb)$$,'complete hierarchy saved atomically');
select is((select count(*) from public.training_blocks),1::bigint,'one block'); select is((select count(*) from public.training_weeks),1::bigint,'one week'); select is((select count(*) from public.training_days),1::bigint,'one day'); select is((select count(*) from public.exercise_prescriptions),1::bigint,'one prescription'); select is((select count(*) from public.prescription_sets),1::bigint,'one set');
select throws_ok($$insert into public.training_blocks(training_program_id,sequence,name) values('a2000000-0000-4000-8000-000000000001',1,'Duplicate')$$,'23505',null,'duplicate block sequence rejected');
select throws_ok($$insert into public.exercise_prescriptions(training_day_id,exercise_id,sequence) select id,'50000000-0000-4000-8000-999999999999',2 from public.training_days limit 1$$,'23503',null,'dangling exercise rejected');
select throws_ok($$insert into public.prescription_sets(exercise_prescription_id,sequence,target_metric,target_min,target_max,load_kind) select id,2,'reps',10,8,'unprescribed' from public.exercise_prescriptions limit 1$$,'23514',null,'reversed target rejected');
select throws_ok($$insert into public.prescription_sets(exercise_prescription_id,sequence,target_metric,target_min,target_max,rir_min,rir_max,load_kind) select id,2,'reps',8,10,3,2,'unprescribed' from public.exercise_prescriptions limit 1$$,'23514',null,'RIR bounds rejected');
select throws_ok($$insert into public.prescription_sets(exercise_prescription_id,sequence,target_metric,target_min,target_max,rest_min_seconds,rest_max_seconds,load_kind) select id,2,'seconds',30,45,120,60,'unprescribed' from public.exercise_prescriptions limit 1$$,'23514',null,'rest bounds rejected');
select throws_ok($$insert into public.prescription_sets(exercise_prescription_id,sequence,target_metric,target_min,target_max,tempo,load_kind) select id,2,'meters',20,20,'slow','unprescribed' from public.exercise_prescriptions limit 1$$,'23514',null,'tempo rejected');
select throws_ok($$insert into public.prescription_sets(exercise_prescription_id,sequence,target_metric,target_min,target_max,load_kind,load_kg) select id,2,'reps',8,8,'athlete_selected',30 from public.exercise_prescriptions limit 1$$,'23514',null,'load consistency rejected');
select lives_ok($$select public.activate_training_program('a2000000-0000-4000-8000-000000000001')$$,'valid activation succeeds'); select is((select status from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),'active','program active');
select throws_ok($$update public.training_blocks set name='Mutation'$$,'55000',null,'active structure update rejected'); select throws_ok($$delete from public.prescription_sets$$,'55000',null,'active structure delete rejected');
select throws_ok($$update public.training_programs set status='draft',activated_at=null where id='a2000000-0000-4000-8000-000000000001'$$,'55000',null,'direct lifecycle bypass rejected'); select throws_ok($$update public.training_programs set name='Rewritten' where id='a2000000-0000-4000-8000-000000000001'$$,'55000',null,'active metadata rewrite rejected'); select throws_ok($$delete from public.training_programs where id='a2000000-0000-4000-8000-000000000001'$$,'55000',null,'active history delete rejected');
select lives_ok($$select public.clone_training_program_as_draft('a2000000-0000-4000-8000-000000000001')$$,'active program clones');
select is((select count(*) from public.training_programs),2::bigint,'clone creates program');
select is((select revision from public.training_programs where status='draft'),2,'clone increments revision');
select is((select supersedes_program_id from public.training_programs where status='draft'),'a2000000-0000-4000-8000-000000000001'::uuid,'lineage points to original');
select isnt((select id from public.training_blocks where training_program_id=(select id from public.training_programs where status='draft')),(select id from public.training_blocks where training_program_id='a2000000-0000-4000-8000-000000000001'),'clone block uses new UUID');
select isnt((select w.id from public.training_weeks w join public.training_blocks b on b.id=w.training_block_id where b.training_program_id=(select id from public.training_programs where status='draft')),(select w.id from public.training_weeks w join public.training_blocks b on b.id=w.training_block_id where b.training_program_id='a2000000-0000-4000-8000-000000000001'),'clone week uses new UUID');
select isnt((select d.id from public.training_days d join public.training_weeks w on w.id=d.training_week_id join public.training_blocks b on b.id=w.training_block_id where b.training_program_id=(select id from public.training_programs where status='draft')),(select d.id from public.training_days d join public.training_weeks w on w.id=d.training_week_id join public.training_blocks b on b.id=w.training_block_id where b.training_program_id='a2000000-0000-4000-8000-000000000001'),'clone day uses new UUID');
select isnt((select ep.id from public.exercise_prescriptions ep join public.training_days d on d.id=ep.training_day_id join public.training_weeks w on w.id=d.training_week_id join public.training_blocks b on b.id=w.training_block_id where b.training_program_id=(select id from public.training_programs where status='draft')),(select ep.id from public.exercise_prescriptions ep join public.training_days d on d.id=ep.training_day_id join public.training_weeks w on w.id=d.training_week_id join public.training_blocks b on b.id=w.training_block_id where b.training_program_id='a2000000-0000-4000-8000-000000000001'),'clone prescription uses new UUID');
select isnt((select ps.id from public.prescription_sets ps join public.exercise_prescriptions ep on ep.id=ps.exercise_prescription_id join public.training_days d on d.id=ep.training_day_id join public.training_weeks w on w.id=d.training_week_id join public.training_blocks b on b.id=w.training_block_id where b.training_program_id=(select id from public.training_programs where status='draft')),(select ps.id from public.prescription_sets ps join public.exercise_prescriptions ep on ep.id=ps.exercise_prescription_id join public.training_days d on d.id=ep.training_day_id join public.training_weeks w on w.id=d.training_week_id join public.training_blocks b on b.id=w.training_block_id where b.training_program_id='a2000000-0000-4000-8000-000000000001'),'clone set uses new UUID');
select is((select name from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),'Programa A','original metadata unchanged by clone');

select public.test_seed_program_root('a2000000-0000-4000-8000-000000000003','Falha atômica');
select lives_ok($$select public.replace_training_program_structure('a2000000-0000-4000-8000-000000000003','{"blocks":[{"sequence":1,"name":"Falha","weeks":[{"sequence":1,"days":[{"sequence":1,"name":"A","prescriptions":[{"sequence":1,"exerciseId":"50000000-0000-4000-8000-000000000001","sets":[{"sequence":1,"targetMetric":"reps","targetMin":8,"targetMax":10,"rirMin":2,"rirMax":2,"restMinSeconds":120,"restMaxSeconds":120,"tempo":null,"loadKind":"athlete_selected","loadKg":null}]}]}]}]}]}'::jsonb)$$,'failure candidate has valid structure');
reset role;
create function public.reject_test_program_activation() returns trigger language plpgsql set search_path='' as $$ begin if new.id='a2000000-0000-4000-8000-000000000003' and new.status='active' then raise exception 'Injected activation failure' using errcode='55000'; end if; return new; end $$;
create trigger training_programs_reject_test_activation before update on public.training_programs for each row execute function public.reject_test_program_activation();
set local role authenticated;
select throws_ok($$select public.activate_training_program('a2000000-0000-4000-8000-000000000003')$$,'55000','Injected activation failure','failed activation rolls back replacement');
select is((select status from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),'active','failed activation leaves current program active');
select is((select archived_at from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),null::timestamptz,'failed activation does not stamp retirement');
reset role; drop trigger training_programs_reject_test_activation on public.training_programs; drop function public.reject_test_program_activation(); set local role authenticated;

select public.test_seed_program_root('a2000000-0000-4000-8000-000000000004','Programa independente');
select lives_ok($$select public.replace_training_program_structure('a2000000-0000-4000-8000-000000000004','{"blocks":[{"sequence":1,"name":"Independente","weeks":[{"sequence":1,"days":[{"sequence":1,"name":"A","prescriptions":[{"sequence":1,"exerciseId":"50000000-0000-4000-8000-000000000001","sets":[{"sequence":1,"targetMetric":"reps","targetMin":8,"targetMax":10,"rirMin":2,"rirMax":2,"restMinSeconds":120,"restMaxSeconds":120,"tempo":null,"loadKind":"athlete_selected","loadKg":null}]}]}]}]}]}'::jsonb)$$,'independent draft has valid structure');
select lives_ok($$select public.activate_training_program('a2000000-0000-4000-8000-000000000004')$$,'independent draft replaces active program');
select is((select status from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),'archived','replacement archives previous active');
select is((select completed_at from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),null::timestamptz,'replacement does not complete previous active');
select ok((select archived_at is not null from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),'replacement stamps retirement');
select is((select status from public.training_programs where id='a2000000-0000-4000-8000-000000000004'),'active','replacement draft becomes active');
select is((select count(*) from public.training_programs where status='active'),1::bigint,'replacement keeps one active program');

select lives_ok($$select public.activate_training_program((select id from public.training_programs where supersedes_program_id='a2000000-0000-4000-8000-000000000001'))$$,'revision replaces current active program');
select is((select status from public.training_programs where id='a2000000-0000-4000-8000-000000000004'),'archived','revision replacement archives current active');
select is((select completed_at from public.training_programs where id='a2000000-0000-4000-8000-000000000004'),null::timestamptz,'revision replacement does not complete current active');
select ok((select archived_at is not null from public.training_programs where id='a2000000-0000-4000-8000-000000000004'),'revision replacement stamps retirement');
select is((select supersedes_program_id from public.training_programs where status='active'),'a2000000-0000-4000-8000-000000000001'::uuid,'active revision preserves lineage');
select is((select name from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),'Programa A','revision replacement preserves original metadata');
select is((select name from public.training_blocks where training_program_id='a2000000-0000-4000-8000-000000000001'),'Base','revision replacement preserves original structure');
select is((select count(*) from public.training_programs where status='active'),1::bigint,'revision replacement keeps one active program');
select throws_ok($$update public.training_blocks set name='Historical rewrite' where training_program_id='a2000000-0000-4000-8000-000000000001'$$,'55000',null,'archived structure remains immutable');

select lives_ok($$select public.transition_training_program((select id from public.training_programs where status='active'),'completed')$$,'explicit completion succeeds');
select is((select status from public.training_programs where supersedes_program_id='a2000000-0000-4000-8000-000000000001'),'completed','explicit completion marks active program completed');
select ok((select completed_at is not null from public.training_programs where supersedes_program_id='a2000000-0000-4000-8000-000000000001'),'explicit completion stamps completed_at');
select is((select archived_at from public.training_programs where supersedes_program_id='a2000000-0000-4000-8000-000000000001'),null::timestamptz,'explicit completion does not stamp archived_at');
select throws_ok($$update public.training_blocks set name='Completed rewrite' where training_program_id=(select id from public.training_programs where status='completed')$$,'55000',null,'completed structure remains immutable');
reset role; set local request.jwt.claim.sub='22222222-2222-4222-8222-222222222222'; set local role authenticated;
select is((select count(*) from public.training_programs),0::bigint,'other athlete cannot select programs'); select is((select count(*) from public.training_blocks),0::bigint,'other athlete cannot select children'); select is((select count(*) from public.prescription_sets),0::bigint,'other athlete cannot select sets'); select is((select count(*) from public.training_programs where id='a2000000-0000-4000-8000-000000000001'),0::bigint,'cross-athlete access blocked');
reset role; select * from finish(); rollback;
